SELECT id, user_id, user_name, target_department_id, target_department_name,
       reason, status, approver_id, approver_name, approve_comment,
       expire_time, apply_time, approve_time
FROM data_scope_apply


        AND user_id = #{userId}


        AND status = #{status}


        AND target_department_id = #{targetDepartmentId}


ORDER BY apply_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM data_scope_apply


        AND user_id = #{userId}


        AND status = #{status}


        AND target_department_id = #{targetDepartmentId}
